"""اردو — اخلاق (virtues_001 … virtues_050)."""

T = {
"virtues_001": ("امام بخاری کی روایت کردہ حدیث کے مطابق اللہ اور آخرت کے دن پر ایمان رکھنے والے کو اپنی بات کے ساتھ کیا کرنا چاہیے؟", ["اچھی بات کہے یا خاموش رہے", "اونچی آواز میں بولے", "کبھی نہ بولے", "افواہیں دہرائے"], "نبی ﷺ نے فرمایا: «جو اللہ اور آخرت کے دن پر ایمان رکھتا ہے وہ اچھی بات کہے یا خاموش رہے۔»"),
"virtues_002": ("اسی حدیث کے مطابق مومن کو اپنے مہمان کے علاوہ اور کس کی عزت کرنی چاہیے؟", ["اپنے پڑوسی کی", "اپنے تاجر کی", "اپنے حریف کی", "ایک اجنبی کی"], "حدیث آگے کہتی ہے: «…اور جو اللہ اور آخرت کے دن پر ایمان رکھتا ہے وہ اپنے پڑوسی کی عزت کرے۔»"),
"virtues_003": ("یہی حدیث گھر آنے پر کس کی عزت کرنے کا ذکر بھی کرتی ہے؟", ["مہمان کی", "صرف پڑوسی کی", "تاجر کی", "دور کے نامعلوم مسافر کی"], "پوری حدیث کہتی ہے: «…جو اللہ اور آخرت کے دن پر ایمان رکھتا ہے وہ اپنے مہمان کی عزت کرے۔»"),
"virtues_004": ("صحیح حدیث کے مطابق مومن کا ایمان مکمل نہیں ہوتا جب تک وہ اپنے بھائی کے لیے وہی پسند نہ کرے جو وہ… کے لیے پسند کرتا ہے۔", ["اپنے آپ", "اپنے مال", "صرف اپنے خاندان", "اپنے ملک"], "نبی ﷺ نے فرمایا: «تم میں سے کوئی مومن نہیں جب تک اپنے بھائی کے لیے وہی پسند نہ کرے جو اپنے لیے پسند کرتا ہے۔»"),
"virtues_005": ("صحیح حدیث کے مطابق سچا مسلمان وہ ہے جس کی زبان اور ___ سے دوسرے لوگ محفوظ رہیں۔", ["ہاتھ", "مال", "نظر", "آواز"], "نبی ﷺ نے فرمایا: «مسلمان وہ ہے جس کی زبان اور ہاتھ سے دوسرے مسلمان محفوظ رہیں۔»"),
"virtues_006": ("قرآن والدین سے حسنِ سلوک کا حکم دیتا ہے اور ان سے ناگواری کا کون سا لفظ کہنے سے بھی منع کرتا ہے؟", ["«اف» (بیزاری کی آواز)", "«نہیں»", "«بس»", "«ٹھہرو»"], "قرآن والدین کے ساتھ بہترین سلوک کا حکم دیتا ہے، حتیٰ کہ حقارت کے معمولی ترین لفظ سے بھی منع کرتا ہے۔"),
"virtues_007": ("قرآن غیبت (غیر موجود شخص کی برائی) کو کس چیز سے تشبیہ دیتا ہے؟", ["اپنے مردہ بھائی کا گوشت کھانے سے", "کھارا پانی پینے سے", "اندھیرے میں چلنے سے", "ریت میں بونے سے"], "«کیا تم میں سے کوئی اپنے مردہ بھائی کا گوشت کھانا پسند کرے گا؟ تم اس سے نفرت کرو گے!»: غیبت اتنی ہی بدنما ہے۔"),
"virtues_008": ("قرآن ایمان والوں کے آپس کے رشتے کو کیسے بیان کرتا ہے؟", ["وہ بھائی بھائی ہیں", "وہ حریف ہیں", "وہ اجنبی ہیں", "وہ کاروباری شریک ہیں"], "«مومن تو بھائی بھائی ہیں، سو اپنے دو بھائیوں میں صلح کراؤ۔»"),
"virtues_009": ("قرآن دوسروں کا مذاق اڑانے کے بارے میں کیا کہتا ہے؟", ["یہ حرام ہے: جن کا مذاق اڑایا جائے وہ اڑانے والوں سے بہتر ہو سکتے ہیں", "دوستوں میں جائز ہے", "مزاحیہ ہو تو جائز ہے", "شاعروں کے لیے مخصوص ہے"], "«کوئی قوم کسی قوم کا مذاق نہ اڑائے: ہو سکتا ہے وہ ان سے بہتر ہوں۔»"),
"virtues_010": ("قرآن کے مطابق اللہ شکر کرنے والے سے کیا وعدہ کرتا ہے؟", ["وہ اسے ضرور اور زیادہ دے گا", "لمبی عمر", "فوری دولت", "ایک سفر"], "«اگر تم شکر کرو گے تو میں تمہیں ضرور اور زیادہ دوں گا۔»"),
"virtues_011": ("قرآن کے مطابق صبر کرنے والوں کو ان کا اجر کیسے دیا جائے گا؟", ["پورا پورا، بے حساب", "ایک ساتھ", "چالیس دن بعد", "ان کے مال کے مطابق"], "«صبر کرنے والوں کو ان کا اجر بے حساب پورا دیا جائے گا۔»"),
"virtues_012": ("«کھاؤ اور پیو، لیکن…»: یہ آیت کیسے آگے بڑھتی ہے؟", ["اسراف نہ کرو", "بانٹو نہیں", "بولو نہیں", "باہر نہ جاؤ"], "«کھاؤ اور پیو، لیکن اسراف نہ کرو: اللہ اسراف کرنے والوں کو پسند نہیں کرتا۔»"),
"virtues_013": ("کون سی آیت، جو اکثر جمعہ کے خطبے میں پڑھی جاتی ہے، اللہ کے احکام کا خلاصہ ہے؟", ["«اللہ عدل اور احسان کا حکم دیتا ہے»", "«اللہ تجارت کا حکم دیتا ہے»", "«اللہ سفر کا حکم دیتا ہے»", "«اللہ خاموشی کا حکم دیتا ہے»"], "«اللہ عدل، احسان اور رشتہ داروں کو دینے کا حکم دیتا ہے…»: ہر جمعہ پڑھی جاتی ہے۔"),
"virtues_014": ("سورۃ المطففین کن کے خلاف «ہلاکت ہے…» سے شروع ہوتی ہے؟", ["ناپ تول میں کمی کرنے والوں", "سونے والوں", "سفر کرنے والوں", "خاموش رہنے والوں"], "«کم دینے والوں کے لیے ہلاکت ہے: جو لیتے وقت پورا لیتے ہیں، مگر دوسروں کو ناپ تول کر دیتے وقت کم دیتے ہیں۔»"),
"virtues_015": ("سورۃ الضحیٰ کے مطابق یتیم اور مانگنے والے کے ساتھ کیسا سلوک ہونا چاہیے؟", ["نہ دبایا جائے نہ جھڑکا جائے", "نظر انداز کیا جائے", "دوسروں کے پاس بھیجا جائے", "بعد میں بات کی جائے"], "«یتیم پر سختی نہ کرو؛ اور مانگنے والے کو نہ جھڑکو۔»"),
"virtues_016": ("قرآن لوگوں سے کیسے بات کرنے کا حکم دیتا ہے؟", ["اچھی بات سے", "بہت دھیمی آواز میں", "جتنا کم ہو سکے", "صرف رشتہ داروں سے"], "«…اور لوگوں سے اچھی بات کہو»: نرم گفتگو خود عبادت ہے۔"),
"virtues_017": ("اپنے بیٹے کو نصیحت میں لقمان چلنے اور تکبر کے بارے میں کیا کہتے ہیں؟", ["زمین پر اکڑ کر نہ چلو", "ہمیشہ تیز چلو", "صرف رات کو چلو", "کبھی اکیلے نہ چلو"], "«تکبر سے لوگوں سے رخ نہ پھیرو، اور زمین پر اکڑ کر نہ چلو۔»"),
"virtues_018": ("بخاری کے مجموعے کی سب سے پہلی حدیث کے مطابق اعمال کا دارومدار کس پر ہے؟", ["نیتوں پر", "نتائج پر", "عادتوں پر", "گواہوں پر"], "«اعمال کا دارومدار نیتوں پر ہے، اور ہر شخص کو وہی ملے گا جس کی اس نے نیت کی۔»"),
"virtues_019": ("بخاری کی حدیث کے مطابق سچائی (صدق) کہاں لے جاتی ہے؟", ["نیکی کی طرف، اور نیکی جنت کی طرف", "دولت کی طرف", "شہرت کی طرف", "طاقت کی طرف"], "«سچائی نیکی کی طرف لے جاتی ہے، اور نیکی جنت کی طرف؛ جھوٹ بدکاری کی طرف لے جاتا ہے، اور بدکاری جہنم کی طرف۔»"),
"virtues_020": ("صحیح حدیث کے مطابق منافق کی تین نشانیاں کیا ہیں؟", ["بات کرے تو جھوٹ بولے، وعدہ کرے تو توڑے، امانت دی جائے تو خیانت کرے", "وہ بہت سوتا، کھاتا اور بولتا ہے", "وہ سفر، تجارت اور گانا کرتا ہے", "وہ کم نماز، کم روزہ اور کم پڑھتا ہے"], "«منافق کی تین نشانیاں ہیں: بات کرے تو جھوٹ بولے، وعدہ کرے تو توڑے، اور امانت دی جائے تو خیانت کرے۔»"),
"virtues_021": ("ایک آدمی نے نبی ﷺ سے نصیحت مانگی؛ آپ نے اسے کئی بار کیا دہرایا؟", ["«غصہ نہ کرو»", "«بہت سفر کرو»", "«کم کھاؤ»", "«اونچا بولو»"], "آدمی نے کہا: «مجھے نصیحت کیجیے۔» آپ نے فرمایا: «غصہ نہ کرو۔» اس نے پھر پوچھا، آپ نے دہرایا: «غصہ نہ کرو۔»"),
"virtues_022": ("نبی ﷺ کے مطابق حقیقی طاقتور کون ہے؟", ["جو غصے کے وقت اپنے آپ پر قابو رکھے", "جو کشتی میں جیتے", "جو سب سے بھاری بوجھ اٹھائے", "جو سب سے تیز دوڑے"], "«طاقتور وہ نہیں جو کشتی میں دوسروں کو پچھاڑ دے؛ طاقتور وہ ہے جو غصے کے وقت اپنے آپ پر قابو رکھے۔»"),
"virtues_023": ("بخاری کی حدیث کے مطابق حیا کس چیز کا حصہ ہے؟", ["ایمان کا", "کمزوری کا", "دولت کا", "قابلِ مذمت شرم کا"], "ایک آدمی کو اپنے بھائی کو حیا پر ملامت کرتے دیکھ کر نبی ﷺ نے فرمایا: «اسے چھوڑو، حیا ایمان کا حصہ ہے۔»"),
"virtues_024": ("نبی ﷺ نے اس آدمی سے کیا فرمایا جس نے فخر کیا کہ اس نے اپنے دس بچوں میں سے کسی کو کبھی نہیں چوما؟", ["«جو رحم نہیں کرتا اس پر رحم نہیں کیا جاتا»", "«تم ٹھیک کہتے ہو»", "«بچے اہم نہیں»", "«یہ ذاتی معاملہ ہے»"], "نبی ﷺ اپنے نواسوں کو چومتے تھے؛ حیران ہونے والے اقرع سے آپ نے فرمایا: «من لا یرحم لا یرحم۔»"),
"virtues_025": ("بخاری کی حدیث کے مطابق ایک آدمی کو کس عمل پر معاف کیا گیا؟", ["پیاسے کتے کو پانی پلانے پر", "کنواں بنانے پر", "درخت لگانے پر", "بھیڑیا بھگانے پر"], "وہ آدمی کنویں میں اترا، اپنے جوتے میں پانی بھرا اور پیاس سے ہانپتے کتے کو پلایا؛ اللہ نے اسے معاف کر دیا۔"),
"virtues_026": ("صحیح حدیث کے مطابق ایک عورت کو کیوں عذاب دیا گیا؟", ["ایک بلی کو بند رکھنے پر، نہ کھلایا نہ کھانے ڈھونڈنے دیا", "بلی بیچنے پر", "بلی کو گھر سے بھگانے پر", "بہت زیادہ بلیاں پالنے پر"], "«ایک عورت کو ایک بلی کی وجہ سے عذاب دیا گیا جسے اس نے مرنے تک بند رکھا: نہ اسے کھلایا نہ زمین کے کیڑے مکوڑے کھانے دیے۔»"),
"virtues_027": ("نبی ﷺ نے کس کے بارے میں فرمایا کہ جبریل اس کی اتنی تاکید کرتے رہے کہ آپ کو لگا وہ اسے وارث بنا دیں گے؟", ["پڑوسی", "مہمان", "یتیم", "مسافر"], "«جبریل مجھے پڑوسی کی تاکید کرتے رہے یہاں تک کہ مجھے لگا وہ اسے وارث بنا دیں گے۔»"),
"virtues_028": ("بخاری کی حدیث کے مطابق ایک مسلمان کے دوسرے مسلمان پر کتنے حق ہیں؟", ["پانچ", "تین", "سات", "دس"], "«سلام کا جواب دینا، بیمار کی عیادت کرنا، جنازے کے ساتھ جانا، دعوت قبول کرنا، اور چھینکنے والے کا جواب دینا۔»"),
"virtues_029": ("جب پوچھا گیا «کون سا اسلام بہتر ہے؟» تو نبی ﷺ نے کیا جواب دیا؟", ["کھانا کھلانا اور جاننے والوں اور نہ جاننے والوں کو سلام کرنا", "مسجدیں بنانا", "بہت سفر کرنا", "کم بولنا"], "«کھانا کھلانا، اور جسے تم جانتے ہو اور جسے نہیں جانتے سب کو سلام کرنا۔»"),
"virtues_030": ("نبی ﷺ ایمان والوں کو ان کی باہمی محبت اور مدد میں کس چیز سے تشبیہ دیتے ہیں؟", ["ایک جسم سے: اگر ایک عضو تکلیف میں ہو تو پورا جسم جاگتا اور بخار میں رہتا ہے", "ایک جنگل سے", "ایک قافلے سے", "ایک ریوڑ سے"], "«مومن اپنی باہمی محبت، رحمت اور شفقت میں ایک جسم کی طرح ہیں۔»"),
"virtues_031": ("نبی ﷺ کے مطابق «سب سے جھوٹی بات» کیا ہے؟", ["بدگمانی", "شاعری", "مذاق", "خاموشی"], "«بدگمانی سے بچو، کیونکہ بدگمانی سب سے جھوٹی بات ہے۔»"),
"virtues_032": ("صحیح حدیث کے مطابق مسلمان زیادہ سے زیادہ کتنے دن اپنے بھائی سے قطع تعلق رکھ سکتا ہے؟", ["تین دن", "سات دن", "ایک مہینہ", "ایک سال"], "«کسی آدمی کے لیے جائز نہیں کہ اپنے بھائی سے تین راتوں سے زیادہ قطع تعلق رکھے… اور دونوں میں بہتر وہ ہے جو پہلے سلام کرے۔»"),
"virtues_033": ("نبی ﷺ کے مطابق ہر نیکی کی، چاہے کتنی چھوٹی ہو، کیا قدر ہے؟", ["وہ صدقہ ہے", "وہ شمار نہیں ہوتی", "وہ ایک دینار کے برابر ہے", "وہ نماز کا بدل ہے"], "«ہر نیکی صدقہ ہے۔»"),
"virtues_034": ("صحیح مسلم کی حدیث کے مطابق ایمان کی سب سے ادنیٰ شاخ کیا ہے؟", ["راستے سے تکلیف دہ چیز ہٹانا", "مسجد بنانا", "ایک پارہ پڑھنا", "ایک دن روزہ رکھنا"], "«ایمان کی ستر سے زیادہ شاخیں ہیں: سب سے اعلیٰ 'لا الہ الا اللہ' ہے، سب سے ادنیٰ راستے سے تکلیف دہ چیز ہٹانا؛ اور حیا ایمان کی ایک شاخ ہے۔»"),
"virtues_035": ("صحیح مسلم کی حدیث کے مطابق طہارت…؟", ["نصف ایمان ہے", "تہائی ایمان ہے", "دسواں حصہ ایمان ہے", "ایمان سے غیر متعلق ہے"], "«طہارت نصف ایمان ہے، اور 'الحمد للہ' ترازو بھر دیتا ہے۔»"),
"virtues_036": ("نبی ﷺ نے فرمایا: «دین خیرخواہی (نصیحت) ہے»: کس کے لیے؟", ["اللہ، اس کی کتاب، اس کے رسول، حکمرانوں اور تمام مسلمانوں کے لیے", "صرف اپنے لیے", "امیروں کے لیے", "اجنبیوں کے لیے"], "پوچھا گیا: «کس کے لیے؟» فرمایا: «اللہ کے لیے، اس کی کتاب کے لیے، اس کے رسول کے لیے، مسلمانوں کے حکمرانوں اور ان کے عام لوگوں کے لیے۔»"),
"virtues_037": ("صحیح مسلم کی حدیث کے مطابق اللہ اپنے بندوں میں کیا دیکھتا ہے؟", ["ان کے دل اور ان کے اعمال", "ان کی شکلیں", "ان کا مال", "ان کی تعداد"], "«اللہ تمہارے جسموں اور شکلوں کو نہیں دیکھتا، بلکہ تمہارے دلوں اور اعمال کو دیکھتا ہے۔»"),
"virtues_038": ("صحیح مسلم کی حدیث کے مطابق جو کسی مومن کی دنیا کی مشکل دور کرے، اللہ اس کے لیے کیا کرتا ہے؟", ["قیامت کے دن اس کی ایک مشکل دور کرتا ہے", "اسے مالدار بنا دیتا ہے", "اسے لمبی عمر دیتا ہے", "اسے مشہور کر دیتا ہے"], "«جو کسی مومن کی دنیا کی مشکل دور کرے، اللہ قیامت کے دن اس کی مشکل دور کرے گا۔»"),
"virtues_039": ("نبی ﷺ کے مطابق جو علم کی تلاش میں راستہ چلے، اللہ اس کے لیے کیا کرتا ہے؟", ["اس کے لیے جنت کا راستہ آسان کر دیتا ہے", "اسے نماز سے معاف کر دیتا ہے", "اسے مالدار بنا دیتا ہے", "اسے بادشاہ بنا دیتا ہے"], "«جو علم کی تلاش میں راستہ چلے، اللہ اس کے لیے جنت کا راستہ آسان کر دیتا ہے۔»"),
"virtues_040": ("بخاری کی حدیث کے مطابق «تم میں سب سے بہتر» کون ہے؟", ["جو قرآن سیکھے اور سکھائے", "جو سب سے اچھا بولے", "جس کے پاس سب سے زیادہ ہو", "جو سب سے زیادہ سفر کرے"], "«تم میں سب سے بہتر وہ ہے جو قرآن سیکھے اور سکھائے۔»"),
"virtues_041": ("نبی ﷺ نے تکبر کی کیا تعریف کی؟", ["حق کو ٹھکرانا اور لوگوں کو حقیر جاننا", "اچھے کپڑے پہننا", "اچھے جوتے پسند کرنا", "تیز چلنا"], "اچھے کپڑے پسند کرنے والے آدمی سے آپ نے فرمایا: «اللہ خوبصورت ہے اور خوبصورتی کو پسند کرتا ہے۔ تکبر حق کو ٹھکرانا اور لوگوں کو حقیر جاننا ہے۔»"),
"virtues_042": ("بخاری کی حدیث کے مطابق کن دو نعمتوں سے بہت سے لوگ فائدہ نہیں اٹھاتے؟", ["صحت اور فراغت", "پیسہ اور شہرت", "طاقت اور خوبصورتی", "خاندان اور دوست"], "«دو نعمتیں ایسی ہیں جن میں بہت سے لوگ خسارے میں ہیں: صحت اور فراغت۔»"),
"virtues_043": ("یہ حدیث مکمل کریں: «مومن ایک ہی… سے دو بار نہیں ڈسا جاتا»", ["«…سوراخ»", "«…بچھو»", "«…دن»", "«…شہد کی مکھی»"], "«لا یلدغ المؤمن من جحر واحد مرتین»: مومن اپنی غلطیوں سے سیکھتا ہے۔"),
"virtues_044": ("نبی ﷺ اچھے ساتھی کو، لوہار کے برعکس، کس سے تشبیہ دیتے ہیں؟", ["مشک بیچنے والے سے", "نانبائی سے", "چرواہے سے", "کپڑے کے تاجر سے"], "«اچھا ساتھی مشک اٹھانے والے کی طرح ہے: وہ تمہیں دیتا ہے، یا تم اس سے خریدتے ہو، یا تمہیں خوشبو آتی ہے؛ برا ساتھی لوہار کی بھٹی کی طرح ہے۔»"),
"virtues_045": ("بخاری کی حدیث کے مطابق ہم میں سے ہر ایک «چرواہے کی طرح» کس کا ذمہ دار ہے؟", ["جو ہماری نگرانی میں ہیں", "موسم کا", "ستاروں کا", "دوسروں کی فصلوں کا"], "«تم میں سے ہر ایک نگہبان ہے، اور ہر ایک اپنی رعیت کا ذمہ دار ہے»: حاکم اپنی رعایا کا، مرد اپنے گھر والوں کا، عورت اپنے گھر کا۔"),
"virtues_046": ("قرآن کے مطابق اگر برائی کو اچھائی سے دور کیا جائے تو کیا ہوتا ہے؟", ["جو دشمن تھا وہ گہرے دوست جیسا ہو جاتا ہے", "برائی زمین سے مٹ جاتی ہے", "آدمی مالدار ہو جاتا ہے", "کچھ نہیں بدلتا"], "«برائی کو اس سے دور کرو جو بہتر ہے، تو جس کے اور تمہارے درمیان دشمنی تھی وہ گہرے دوست جیسا ہو جائے گا» (41:34)۔"),
"virtues_047": ("سورۃ الفرقان کے مطابق «رحمٰن کے بندے» بھڑکانے والے جاہلوں کو کیا جواب دیتے ہیں؟", ["وہ کہتے ہیں: «سلام!»", "وہ غصے سے جواب دیتے ہیں", "وہ ان کا مذاق اڑاتے ہیں", "وہ انہیں مارتے ہیں"], "«رحمٰن کے بندے زمین پر عاجزی سے چلتے ہیں، اور جب جاہل ان سے مخاطب ہوں تو کہتے ہیں: سلام!» (25:63)۔"),
"virtues_048": ("قرآن عہد (وعدہ) کے بارے میں کیا کہتا ہے؟", ["«عہد پورا کرو، کیونکہ عہد کے بارے میں پوچھا جائے گا»", "«وعدہ کسی کو پابند نہیں کرتا»", "«صرف امیروں سے وعدہ کرو»", "«کبھی وعدہ نہ کرو»"], "«اور عہد پورا کرو؛ بے شک عہد کے بارے میں پوچھا جائے گا» (17:34)۔"),
"virtues_049": ("قرآن کن کے بارے میں کہتا ہے کہ وہ «شیطانوں کے بھائی» ہیں؟", ["فضول خرچ", "مسافر", "تاجر", "شاعر"], "«فضول خرچ شیطانوں کے بھائی ہیں، اور شیطان اپنے رب کا ناشکرا ہے» (17:27)۔"),
"virtues_050": ("«دو کلمے جو زبان پر ہلکے، ترازو میں بھاری، اور رحمٰن کو محبوب ہیں» کون سے ہیں؟", ["«سبحان اللہ وبحمدہ، سبحان اللہ العظیم»", "«اللہ اکبر، الحمد للہ»", "«لا الہ الا اللہ، محمد رسول اللہ»", "«بسم اللہ، ما شاء اللہ»"], "«دو کلمے زبان پر ہلکے، ترازو میں بھاری، رحمٰن کو محبوب: سبحان اللہ وبحمدہ، سبحان اللہ العظیم۔»"),
}
